<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ArrowLeft,Download,Send,Plus,Copy,Pencil,ExternalLink,Trash2,RefreshCw,Ban } from 'lucide-vue-next'
import { api,json,downloadPdf } from '../../api/client'
import { useAuth } from '../../stores/auth'
import { formatMoney } from '../../utils/money'
import { formatDate } from '../../utils/formatDate'
import type { Invoice } from '../../types'
import StatusBadge from '../../components/StatusBadge.vue'
import SendInvoiceModal from '../../components/SendInvoiceModal.vue'
import PaymentModal from '../../components/PaymentModal.vue'
const route=useRoute(),router=useRouter(),auth=useAuth(),invoice=ref<Invoice|null>(null),error=ref(''),success=ref(''),sendOpen=ref(false),paymentOpen=ref(false),busy=ref(false)
async function load(){try{invoice.value=await api<Invoice>('/invoices/'+route.params.id)}catch(e){error.value=(e as Error).message}}
onMounted(load)
async function action(kind:string){if(!invoice.value)return;if(kind==='void'&&!confirm('Void this invoice? This action is final.'))return;busy.value=true;try{const result=await api<Invoice>('/invoices/'+invoice.value.id+'/'+kind,json('POST',{}));if(kind==='duplicate')router.push('/invoices/'+result.id);else await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function pdf(){if(!invoice.value)return;try{await downloadPdf(invoice.value.id,invoice.value.number)}catch(e){error.value=(e as Error).message}}
async function removePayment(id:number){if(!confirm('Remove this payment? The invoice balance will be recalculated.'))return;try{await api('/payments/'+id,{method:'DELETE'});await load()}catch(e){error.value=(e as Error).message}}
async function sent(){sendOpen.value=false;success.value='Delivery queued. Refresh the history to see progress.';await load()}
async function paid(){paymentOpen.value=false;success.value='Payment recorded. Your balance is up to date.';await load()}
async function deliveryNote(){await actionDelivery()}
async function actionDelivery(){if(!invoice.value)return;busy.value=true;try{const d=await api<{id:number}>('/invoices/'+invoice.value.id+'/delivery-note',json('POST',{}));router.push('/delivery-notes/'+d.id)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><RouterLink to="/invoices" class="back-link"><ArrowLeft :size="16"/>Back to invoices</RouterLink><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="success" role="status">{{ success }}</p><template v-if="invoice"><div class="page-heading"><div><span class="eyebrow">INVOICE DETAILS</span><h1>{{ invoice.number }}<span class="heading-dot">.</span></h1><StatusBadge :status="invoice.status"/></div><div class="actions wrap"><button class="button secondary" @click="pdf"><Download :size="16"/>PDF</button><button class="button primary" @click="sendOpen=true" :disabled="invoice.status==='void'||busy"><Send :size="16"/>Send invoice</button></div></div><div class="editor-grid"><section class="panel invoice-sheet"><div class="invoice-brand"><div><img v-if="invoice.business?.logo_url" :src="invoice.business.logo_url" class="business-logo" alt="Business logo"><h2>{{ invoice.business?.name }}</h2><p class="muted">{{ invoice.business?.address }}<br>{{ invoice.business?.email }}</p></div><div class="right"><h2 :style="{color:invoice.business?.brand_color}">INVOICE</h2><p>{{ invoice.number }}</p><p v-if="invoice.po_number">PO: {{ invoice.po_number }}</p></div></div><div class="invoice-meta"><div><span class="eyebrow">BILL TO</span><h3>{{ invoice.client.name }}</h3><p>{{ invoice.client.company }}<br>{{ invoice.client.email }}<br>{{ invoice.client.phone }}</p></div><div><span class="eyebrow">ISSUED</span><p>{{ formatDate(invoice.issue_date) }}</p><span class="eyebrow">DUE DATE</span><p>{{ formatDate(invoice.due_date) }}</p></div></div><div class="table-wrap"><table><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody><tr v-for="item in invoice.items" :key="item.id"><td>{{ item.description }}</td><td>{{ item.quantity }}</td><td>{{ formatMoney(item.unit_price_kobo,invoice.currency,invoice.currency_minor_units) }}</td><td class="money">{{ formatMoney(item.line_total_kobo,invoice.currency,invoice.currency_minor_units) }}</td></tr></tbody></table></div><div class="invoice-totals"><div class="total-row"><span>Subtotal</span><span>{{ formatMoney(invoice.subtotal_kobo,invoice.currency,invoice.currency_minor_units) }}</span></div><div class="total-row"><span>Discount</span><span>− {{ formatMoney(invoice.discount_kobo,invoice.currency,invoice.currency_minor_units) }}</span></div><div class="total-row"><span>Tax ({{ invoice.tax_percent }}%)</span><span>{{ formatMoney(invoice.tax_kobo,invoice.currency,invoice.currency_minor_units) }}</span></div><div class="total-row"><strong>Total</strong><strong>{{ formatMoney(invoice.total_kobo,invoice.currency,invoice.currency_minor_units) }}</strong></div><div class="total-row"><span>Paid</span><span>{{ formatMoney(invoice.amount_paid_kobo,invoice.currency,invoice.currency_minor_units) }}</span></div><div class="total-row grand-total"><strong>Balance due</strong><strong>{{ formatMoney(invoice.balance_kobo,invoice.currency,invoice.currency_minor_units) }}</strong></div></div><div class="invoice-notes"><h3>Payment instructions</h3><p>{{ invoice.business?.payment_instructions||'Contact the business for payment instructions.' }}</p><template v-if="invoice.notes"><h3>Notes</h3><p>{{ invoice.notes }}</p></template><template v-if="invoice.terms"><h3>Terms</h3><p>{{ invoice.terms }}</p></template></div></section><aside><section class="panel form-panel"><span class="eyebrow">OUTSTANDING BALANCE</span><h2 class="balance-value">{{ formatMoney(invoice.balance_kobo,invoice.currency,invoice.currency_minor_units) }}</h2><button v-if="!['draft','paid','void'].includes(invoice.status)" class="button primary wide" @click="paymentOpen=true"><Plus :size="17"/>Record payment</button><a :href="invoice.public_url" target="_blank" rel="noopener" class="button secondary wide spaced"><ExternalLink :size="16"/>Public invoice</a><RouterLink v-if="invoice.status==='draft'" :to="'/invoices/'+invoice.id+'/edit'" class="button ghost wide"><Pencil :size="16"/>Edit draft</RouterLink><button v-if="!['draft','void'].includes(invoice.status)" class="button ghost wide" :disabled="busy" @click="deliveryNote">Create delivery note</button><button class="button ghost wide" @click="action('duplicate')" :disabled="busy"><Copy :size="16"/>Duplicate invoice</button><button v-if="auth.manager&&!['paid','void'].includes(invoice.status)" class="button ghost wide danger-text" @click="action('void')" :disabled="busy||invoice.amount_paid_kobo>0"><Ban :size="16"/>Void invoice</button></section><section class="panel form-panel spaced"><h2>Payments <span class="count">{{ invoice.payments.length }}</span></h2><p v-if="!invoice.payments.length" class="muted">Payments will appear here once recorded.</p><div v-for="payment in invoice.payments" :key="payment.id" class="activity-row"><div><strong>{{ formatMoney(payment.amount_kobo,invoice.currency,invoice.currency_minor_units) }}</strong><small>{{ payment.method.replace('_',' ') }} · {{ formatDate(payment.paid_on) }}</small><small>{{ payment.reference }}</small></div><button v-if="auth.manager" class="icon-button danger-text" @click="removePayment(payment.id)" aria-label="Remove payment"><Trash2 :size="15"/></button></div></section><section class="panel form-panel spaced"><div class="panel-heading compact"><h2>Delivery history</h2><button class="icon-button" @click="load" aria-label="Refresh delivery history"><RefreshCw :size="16"/></button></div><p v-if="!invoice.messages.length" class="muted">Ready when you are. Send this invoice to your client.</p><div v-for="message in invoice.messages" :key="message.id" class="delivery-row"><div class="actions between"><strong>{{ message.channel }}</strong><StatusBadge :status="message.status"/></div><small>{{ message.recipient }} · {{ message.attempts }} attempts</small><small v-if="message.provider_message_id?.startsWith('log-only')">Demo log-only delivery</small><p v-if="message.error" class="error">{{ message.error }}</p></div></section></aside></div><SendInvoiceModal v-if="sendOpen" :invoice="invoice" @close="sendOpen=false" @sent="sent"/><PaymentModal v-if="paymentOpen" :invoice="invoice" @close="paymentOpen=false" @saved="paid"/></template><div v-else-if="!error" class="loading">Loading invoice…</div></template>